import {recipe,svg,snippet,animationDuration} from '/studio/core.mjs';
import {gradientTool,drawSVG,png} from '/studio/gradient.mjs';
import {rampTool} from '/studio/ramps.mjs';
import {asciiTool} from '/studio/ascii.mjs';
import {patternTool} from '/studio/patterns.mjs';
import {motionTool} from '/studio/motion.mjs';
import {typographyTool} from '/studio/typography.mjs';
const $=id=>document.getElementById(id),A=window.RepoAccount,KEEP='reposhelf.studio.resume.v1',PAGE=24;
let active='gradient',initialized=false,timer,backgrounds=[],images=[],selectedBackground=null,selectedImage=null,backgroundLimit=PAGE,imageLimit=PAGE,saved=new Set(),savedFor=null;
function status(message,error=false){$('studio-status').textContent=message;$('studio-status').dataset.error=String(error)}
const gradient=gradientTool({change,status}),ramps=rampTool({change,status}),ascii=asciiTool({change,status});
const patterns=patternTool({change,status}),motion=motionTool({change,status}),typography=typographyTool({change,status});
window.RepoProfileMenu.install({collectionHref:'/#collection',toast:status});
function currentState(){return {v:1,tool:active,gradient:gradient.get(),ramps:ramps.get(),ascii:ascii.get(),patterns:patterns.get(),motion:motion.get(),typography:typography.get(),background:selectedBackground?.id,image:selectedImage?.id}}
function change(){if(!initialized)return;clearTimeout(timer);timer=setTimeout(()=>writeState(),250)}
function sharedState(){const s=currentState();if(['patterns','motion','typography'].includes(active))return {v:1,tool:active,[active]:s[active]};delete s.patterns;delete s.motion;delete s.typography;return s}
function writeState(){const hash=active==='ui'?(/^#ui\/[a-z0-9-]{1,80}$/.test(location.hash)?location.hash:'#ui'):active==='backgrounds'&&selectedBackground?'#bg/'+selectedBackground.id:active==='images'&&selectedImage?'#img/'+selectedImage.id:'#s='+encodeURIComponent(JSON.stringify(sharedState()));if(hash.length>6000){status('This look is too long to share. Shorten the text before sharing.',true);return false}history.replaceState(null,'',location.pathname+hash);return true}
function switchTab(name,focus=false){if(!['gradient','ramps','ascii','backgrounds','images','ui','patterns','motion','typography'].includes(name)||name==='images'&&!images.length)return;active=name;motion.activate(name==='motion');typography.activate?.(name==='typography');for(const button of document.querySelectorAll('.studio-tabs [role=tab]')){const on=button.id==='studio-tab-'+name;button.setAttribute('aria-selected',String(on));button.tabIndex=on?0:-1;$(button.getAttribute('aria-controls')).hidden=!on;if(on&&focus)button.focus()}if(name==='ui')window.dispatchEvent(new Event('reposhelf-ui-activate'));change()}
for(const button of document.querySelectorAll('.studio-tabs [role=tab]')){button.onclick=()=>switchTab(button.id.replace('studio-tab-',''));button.onkeydown=e=>{const tabs=[...document.querySelectorAll('.studio-tabs [role=tab]:not([hidden])')],i=tabs.indexOf(button);let next=e.key==='ArrowRight'?(i+1)%tabs.length:e.key==='ArrowLeft'?(i+tabs.length-1)%tabs.length:e.key==='Home'?0:e.key==='End'?tabs.length-1:-1;if(next>=0){e.preventDefault();switchTab(tabs[next].id.replace('studio-tab-',''),true)}}}
function remember(){try{sessionStorage.setItem(KEEP,JSON.stringify({at:Date.now(),state:currentState()}))}catch{}}
function signin(){remember();window.RepoProfileMenu.open();for(const a of $('account').querySelectorAll('a[href^="/api/auth?action=start"]')){const u=new URL(a.href);u.searchParams.set('return','/studio.html');a.href=u.pathname+u.search}status('Sign in to export or save. Your Studio settings will be here when you return.')}
async function authorize(){if(!A.ready)await A.refresh();if(!A.user){signin();return false}try{await A.request('/api/prompts?area=studio-access');return true}catch(e){if(e.status===401){signin();return false}if(e.status===428){remember();location.href='/legal.html?return=studio';return false}throw e}}
function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function copy(text){try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.top='0';document.body.append(area);area.focus();area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('Copy was unavailable. Try downloading the file instead.')}}
function track(kind,source,id){if(source&&id)A.track(kind,source+'/'+id)}
async function performExport(button){if(button.disabled)return;button.disabled=true;try{
  if(!await authorize())return;const [tool,format]=button.dataset.export.split(':');
  if(tool==='gradient'){const r=gradient.get();if(format==='png')download(await png(svg(r,gradient.width(),gradient.width()*9/16),gradient.width()),'reposhelf-background.png');else if(format==='svg')download(new Blob([svg(r)],{type:'image/svg+xml'}),'reposhelf-background.svg');else await copy(snippet(r,format))}
  else if(tool==='ramps'){const text=ramps.export(format);if(format==='json')download(new Blob([text],{type:'application/json'}),'reposhelf-colours.json');else await copy(text)}
  else if(tool==='ascii'){if(format==='copy')await copy(ascii.text());else if(format==='txt')download(new Blob([ascii.text()],{type:'text/plain;charset=utf-8'}),'reposhelf-ascii.txt');else if(format==='svg')download(new Blob([ascii.svg()],{type:'image/svg+xml'}),'reposhelf-ascii.svg');else {const source=ascii.svg(),doc=new DOMParser().parseFromString(source,'image/svg+xml');download(await png(source,Number(doc.documentElement.getAttribute('width')),Number(doc.documentElement.getAttribute('height'))),'reposhelf-ascii.png')}}
  else if(tool==='patterns'){if(format==='svg')download(new Blob([patterns.tile()],{type:'image/svg+xml'}),'reposhelf-pattern-tile.svg');else if(format==='png')download(await png(patterns.svg(),1920),'reposhelf-pattern.png');else await copy(patterns.css())}
  else if(tool==='motion'){if(format==='html')download(new Blob([motion.html()],{type:'text/html;charset=utf-8'}),'reposhelf-motion.html');else if(format==='png')download(await png(motion.svg(),1920),'reposhelf-motion-frame.png');else await copy(motion.css())}
  else if(tool==='typography'){if(format==='effect-svg')download(new Blob([typography.effects.svg()],{type:'image/svg+xml'}),'reposhelf-text.svg');else if(format==='effect-png')download(await png(typography.effects.svg(),1920),'reposhelf-text.png');else if(format==='effect-html')download(new Blob([typography.effects.html()],{type:'text/html;charset=utf-8'}),'reposhelf-text.html');else if(format==='effect-code')await copy(typography.effects.html());else if(format==='json')download(new Blob([typography.json()],{type:'application/json'}),'reposhelf-type-tokens.json');else await copy(typography.css())}
  else if(tool==='backgrounds'){if(!selectedBackground)throw Error('Choose a background first.');const item=selectedBackground,d=await A.request('/api/prompts?area=studio-background&id='+encodeURIComponent(item.id));if(format==='png')download(await png(d.svg,2560),item.id+'.png');else if(format==='svg')download(new Blob([d.svg],{type:'image/svg+xml'}),item.id+'.svg');else await copy(d[format]);track(format==='png'||format==='svg'?'zip_download':'code_copy','bg',item.id)}
  else if(tool==='images'){if(!selectedImage)throw Error('Choose an image first.');const item=selectedImage;const d=await A.request('/api/prompts?area=image-download&id='+encodeURIComponent(item.id)+'&variant='+encodeURIComponent(format));const a=document.createElement('a');a.href=d.url;a.rel='noreferrer noopener';a.download=d.filename;a.target='_blank';document.body.append(a);a.click();a.remove();track('zip_download','img',item.id)}
  status(format==='effect-code'||format==='css'||format==='react'||format==='tailwind'||format==='copy'?'Copied. Ready for your project.':'Your download is ready.');
 }catch(e){if(e.status===428){remember();location.href='/legal.html?return=studio'}else status(e.message,true)}finally{button.disabled=false}}
document.querySelectorAll('[data-export]').forEach(button=>button.onclick=()=>performExport(button));
$('studio-share').onclick=async()=>{if(!writeState())return;try{await copy(location.href);status(active==='ascii'?'Link copied. Uploaded images are not included.':'Link copied. Anyone can open this look.')}catch(e){status(e.message,true)}};
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function filtered(list,prefix){const search=$(prefix+'-search').value.trim().toLowerCase(),category=$(prefix+'-category').value,colour=$(prefix+'-colour').value;return list.filter(i=>(!category||i.category===category)&&(!colour||i.colour===colour)&&(!search||`${i.title} ${i.description} ${(i.tags||[]).join(' ')}`.toLowerCase().includes(search)))}
function paintSaves(){for(const b of document.querySelectorAll('[data-save]')){const on=saved.has(b.dataset.save);b.setAttribute('aria-pressed',String(on));b.textContent=on?'Saved · remove':'Save to My collection'}}
async function save(source,item){try{if(!await authorize())return;const key='ss:'+source+'/'+item.id,was=saved.has(key);await A.request('/api/collection',{method:was?'DELETE':'PUT',body:JSON.stringify({id:key})});was?saved.delete(key):saved.add(key);paintSaves();status(was?'Removed from My collection.':'Saved to My collection.')}catch(e){status(e.message,true)}}
function gallery(list,prefix,source,limit){const selected=filtered(list,prefix),grid=$(prefix+'-grid');grid.replaceChildren();for(const item of selected.slice(0,limit)){const li=element('li','studio-item'),open=element('button','studio-item-open');open.type='button';open.setAttribute('aria-label','Preview '+item.title);const img=element('img');img.src=source==='bg'?'/studio/thumbs/'+item.id+'.webp':'/studio/images/thumbs/'+item.id+'.webp';img.alt=item.title;img.width=640;img.height=360;img.loading='lazy';img.decoding='async';open.append(img);const caption=element('span','studio-item-caption');caption.append(element('strong',null,item.title),element('span',null,item.category));open.append(caption);open.onclick=()=>source==='bg'?openBackground(item,true):openImage(item,true);const meta=element('div','studio-item-meta'),button=element('button','studio-save','Save to My collection');button.type='button';button.dataset.save='ss:'+source+'/'+item.id;button.onclick=()=>save(source,item);meta.append(element('span',null,source==='img'?(item.files?.loop?'AI-generated · animated option':'AI-generated'):'Original background'),button);li.append(open,meta);grid.append(li)}$(prefix+'-count').textContent=selected.length?`${selected.length} ${prefix==='background'?'backgrounds':'images'} · showing ${Math.min(limit,selected.length)}`:'No matches. Try another category, colour or search.';$(prefix+'-more').hidden=limit>=selected.length;paintSaves()}
function renderBackgrounds(){gallery(backgrounds,'background','bg',backgroundLimit)}function renderImages(){gallery(images,'image','img',imageLimit)}
for(const prefix of ['background','image']){$(prefix+'-filters').onsubmit=e=>e.preventDefault();for(const key of ['search','category','colour'])$(prefix+'-'+key).oninput=()=>{if(prefix==='background'){backgroundLimit=PAGE;renderBackgrounds()}else{imageLimit=PAGE;renderImages()}}}
$('background-more').onclick=()=>{backgroundLimit+=PAGE;renderBackgrounds()};$('image-more').onclick=()=>{imageLimit+=PAGE;renderImages()};
let previewEpoch=0;
function revealSelection(prefix){const title=$(prefix+'-title');$(prefix+'-editor').scrollIntoView({block:'start',behavior:'instant'});title.setAttribute('tabindex','-1');title.focus({preventScroll:true})}
async function openBackground(item,reveal=false){selectedBackground=item;switchTab('backgrounds');$('background-editor').hidden=false;$('background-title').textContent=item.title;if(reveal)revealSelection('background');$('background-description').textContent=item.description;$('background-save').dataset.save='ss:bg/'+item.id;$('background-save').onclick=()=>save('bg',item);paintSaves();const epoch=++previewEpoch,temp=document.createElement('canvas');temp.width=960;temp.height=540;await drawSVG(temp,svg(item.recipe,960,540));if(epoch!==previewEpoch)return;$('background-canvas').getContext('2d').drawImage(temp,0,0);$('background-stage').style.setProperty('--studio-animation-duration',animationDuration(item.recipe)+'s');$('background-stage').classList.toggle('is-animated',item.recipe.animate);track('prompt_view','bg',item.id);change()}
$('background-edit').onclick=()=>{if(!selectedBackground)return;gradient.set(selectedBackground.recipe);switchTab('gradient');$('studio-gradient').scrollIntoView({block:'start'})};$('background-close').onclick=()=>{previewEpoch++;selectedBackground=null;$('background-editor').hidden=true;change()};
function openImage(item,reveal=false){selectedImage=item;switchTab('images');$('image-editor').hidden=false;$('image-title').textContent=item.title;if(reveal)revealSelection('image');$('image-loop-download').hidden=!item.files?.loop;$('image-motion-toggle').hidden=!item.animation?.preview;$('image-motion-toggle').textContent='Play animation';$('image-motion-toggle').setAttribute('aria-pressed','false');$('image-preview').src='/studio/images/thumbs/'+item.id+'.webp';$('image-preview').alt=item.title;$('image-details').textContent=`${item.description||''} AI-generated. Original: ${item.width} × ${item.height} pixels.${item.upscaled?' The 2560-pixel version is enlarged from the original.':''}${item.files?.loop?' Includes an 8-second, silent 1280 × 720 MP4 loop with gentle framing movement derived from the still artwork.':''}`;$('image-save').dataset.save='ss:img/'+item.id;$('image-save').onclick=()=>save('img',item);paintSaves();track('prompt_view','img',item.id);change()}
$('image-close').onclick=()=>{selectedImage=null;$('image-editor').hidden=true;change()};
async function loadSaved(){const user=A.user?.id||null;if(savedFor===user)return;savedFor=user;saved=new Set();if(user)try{let cursor;do{const data=await A.request('/api/collection?kind=prompts'+(cursor?'&cursor='+encodeURIComponent(cursor):''));if(savedFor!==user)return;for(const i of data.items)saved.add(i.id);cursor=data.nextCursor}while(cursor)}catch(e){status('Saved resources could not be loaded. '+e.message,true)}paintSaves()}
window.addEventListener('reposhelf-account',()=>{if(A.ready)void loadSaved()});
function applyState(s){if(s?.v!==1)return;for(const [key,tool] of Object.entries({gradient,ramps,ascii,patterns,motion,typography}))if(s[key]&&typeof s[key]==='object')tool.set(s[key]);switchTab(s.tool);const bg=backgrounds.find(i=>i.id===s.background),img=images.find(i=>i.id===s.image);if(bg&&s.tool==='backgrounds')void openBackground(bg);if(img&&s.tool==='images')openImage(img)}
function fromHash(){const hash=location.hash;const experiment=/^#(patterns|motion|typography)$/.exec(hash);if(experiment){switchTab(experiment[1]);return}if(/^#ui(?:\/[a-z0-9-]{1,80})?$/.test(hash)){switchTab('ui');return}const bg=/^#bg\/([a-z0-9-]{1,80})$/.exec(hash),img=/^#img\/([a-z0-9-]{1,80})$/.exec(hash);if(bg){const item=backgrounds.find(i=>i.id===bg[1]);if(item)void openBackground(item);return}if(img){const item=images.find(i=>i.id===img[1]);if(item)openImage(item);return}if(hash.startsWith('#s=')&&hash.length<=6000)try{applyState(JSON.parse(decodeURIComponent(hash.slice(3))))}catch{history.replaceState(null,'',location.pathname+(location.search||''))}}
window.addEventListener('hashchange',fromHash);
window.addEventListener('reposhelf-ui-open',()=>switchTab('ui'));
fromHash();
async function catalogue(url){const res=await fetch(url,{cache:'no-cache'});if(!res.ok)throw Error('The Studio catalogue could not be loaded. Reload to try again.');const data=await res.json();if(!Array.isArray(data))throw Error('The Studio catalogue could not be read.');return data}
(async()=>{try{
  [backgrounds,images]=await Promise.all([catalogue('/studio/index.json'),catalogue('/studio/images/index.json')]);
  for(const [list,prefix] of [[backgrounds,'background'],[images,'image']])for(const category of [...new Set(list.map(i=>i.category))]){const option=element('option',null,category);option.value=category;$(prefix+'-category').append(option)}
  $('studio-tab-images').hidden=!images.length;renderBackgrounds();renderImages();
  let resumed=false;try{const data=JSON.parse(sessionStorage.getItem(KEEP)||'null');sessionStorage.removeItem(KEEP);if(data&&!/^#ui(?:\/|$)/.test(location.hash)&&Date.now()-data.at<3600000){applyState(data.state);resumed=true}}catch{}
  if(!resumed)fromHash();initialized=true;if(A.ready)void loadSaved();
}catch(e){$('background-count').textContent=e.message;status(e.message,true);initialized=true}})();

$('image-motion-toggle').onclick=()=>{if(!selectedImage?.animation?.preview)return;const button=$('image-motion-toggle'),playing=button.getAttribute('aria-pressed')!=='true';$('image-preview').src=playing?selectedImage.animation.preview:'/studio/images/thumbs/'+selectedImage.id+'.webp';button.setAttribute('aria-pressed',String(playing));button.textContent=playing?'Pause animation':'Play animation';};

for(const prefix of ['background','image'])$(prefix+'-browse').onclick=()=>{$(prefix+'-filters').scrollIntoView({block:'start',behavior:'instant'});$(prefix+'-search').focus({preventScroll:true})};
